//! Operator-only FD transfer: clone in host namespace, then attach after idmap.
//! Receipts describe mounts, not keys, grants or identity lifecycle authority.
use anyhow::{Context, Result, bail, ensure};
use serde::Deserialize;
use serde_json::Value;
use std::ffi::CString;
use std::fs::{self, File, OpenOptions};
use std::io::Read;
use std::os::fd::{AsRawFd, FromRawFd, OwnedFd};
use std::os::unix::ffi::OsStrExt;
use std::os::unix::fs::{MetadataExt, OpenOptionsExt};
use std::path::{Path, PathBuf};
use uuid::Uuid;

const TARGET: &str = "opt/run-mounts/3tched";
const BTRFS_MAGIC: libc::c_long = 0x9123_683e;
const FUSE_MAGIC: libc::c_long = 0x6573_5546;
const FS_INFO: libc::c_ulong = 0x8400_941f;

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct LungsReceipt {
    #[serde(default)]
    version: Option<u64>,
    #[serde(default)]
    container_label: Option<String>,
    #[serde(default)]
    instance_uuid: Option<String>,
    boot_id: String,
    session: String,
    target: PathBuf,
    pid: u32,
    start: String,
    args: Vec<String>,
    mount_id: String,
}

fn trusted(path: &Path) -> Result<()> {
    ensure!(
        path.is_absolute() && fs::canonicalize(path)? == path,
        "noncanonical trusted path"
    );
    for ancestor in path.ancestors() {
        let m = fs::symlink_metadata(ancestor)?;
        ensure!(
            !m.file_type().is_symlink() && m.uid() == 0,
            "trusted path owner changed"
        );
        ensure!(
            m.mode() & 0o022 == 0 || (m.is_dir() && m.mode() & 0o1000 != 0),
            "trusted path is writable"
        );
    }
    Ok(())
}

fn json(path: &Path) -> Result<Value> {
    trusted(path)?;
    let f = OpenOptions::new()
        .read(true)
        .custom_flags(libc::O_NOFOLLOW | libc::O_CLOEXEC)
        .open(path)?;
    let m = f.metadata()?;
    ensure!(
        m.is_file() && m.uid() == 0 && m.mode() & 0o777 == 0o600 && m.len() <= 16384,
        "unsafe mount receipt"
    );
    let mut bytes = Vec::new();
    f.take(16385).read_to_end(&mut bytes)?;
    ensure!(bytes.len() <= 16384, "oversized mount receipt");
    Ok(serde_json::from_slice(&bytes)?)
}

fn string<'a>(value: &'a Value, field: &str) -> Result<&'a str> {
    value[field]
        .as_str()
        .with_context(|| format!("missing receipt field {field}"))
}

fn container_label(name: &str) -> Option<String> {
    let number = name.strip_prefix("ID-")?;
    let ordinal = number.parse::<i64>().ok()?;
    (ordinal >= 0 && ordinal.to_string() == number)
        .then(|| format!("ID_{number}"))
}

fn receipt_present(path: &Path) -> Result<bool> {
    match fs::symlink_metadata(path) {
        Ok(_) => Ok(true),
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => Ok(false),
        Err(error) => Err(error.into()),
    }
}

fn storage_receipt(state: &Path, name: &str) -> Result<Value> {
    let legacy = state.join(name).join("state.json");
    if let Some(label) = container_label(name) {
        let labelled = state.join(&label).join("state.json");
        if receipt_present(&labelled)? {
            ensure!(
                !receipt_present(&legacy)?,
                "multiple storage receipts select the same native instance"
            );
            let storage = json(&labelled)?;
            ensure!(
                storage["version"] == 2 && storage["container_label"] == label,
                "label storage receipt differs from native instance"
            );
            return Ok(storage);
        }
    }
    let storage = json(&legacy)?;
    ensure!(
        storage["version"] == 1,
        "legacy storage receipt version differs"
    );
    Ok(storage)
}

fn lungs_directory_name<'a>(storage: &'a Value, name: &str, native_uuid: &'a str) -> Result<&'a str> {
    // Receipt version, never directory existence or name spelling, selects
    // the layout. Existing version-1 mounts retain their native UUID path.
    match storage["version"].as_u64() {
        Some(1) => Ok(native_uuid),
        Some(2) => {
            let label = string(storage, "container_label")?;
            ensure!(
                container_label(name).as_deref() == Some(label),
                "container label differs from native instance"
            );
            Ok(label)
        }
        _ => bail!("unsupported storage receipt version"),
    }
}

fn verify_lungs_layout(storage: &Value, receipt: &LungsReceipt, native_uuid: &str) -> Result<()> {
    match storage["version"].as_u64() {
        Some(1) => ensure!(
            receipt.version.is_none()
                && receipt.container_label.is_none()
                && receipt.instance_uuid.is_none(),
            "legacy lungs receipt layout changed"
        ),
        Some(2) => ensure!(
            receipt.version == Some(2)
                && receipt.container_label.as_deref() == Some(string(storage, "container_label")?)
                && receipt.instance_uuid.as_deref() == Some(native_uuid),
            "label lungs receipt native UUID or container label changed"
        ),
        _ => bail!("unsupported storage receipt version"),
    }
    Ok(())
}

fn fd_open(path: &Path, flags: i32) -> Result<OwnedFd> {
    let path = CString::new(path.as_os_str().as_bytes())?;
    // SAFETY: nul-terminated path; a successful descriptor is uniquely owned.
    let fd = unsafe { libc::open(path.as_ptr(), flags | libc::O_CLOEXEC) };
    ensure!(fd >= 0, "open failed: {}", std::io::Error::last_os_error());
    Ok(unsafe { OwnedFd::from_raw_fd(fd) })
}

fn proc_open(proc: &OwnedFd, name: &str, flags: i32) -> Result<OwnedFd> {
    let name = CString::new(name)?;
    // SAFETY: proc is a held directory FD and name is fixed by this module.
    let fd = unsafe { libc::openat(proc.as_raw_fd(), name.as_ptr(), flags | libc::O_CLOEXEC) };
    ensure!(
        fd >= 0,
        "process entry unavailable: {}",
        std::io::Error::last_os_error()
    );
    Ok(unsafe { OwnedFd::from_raw_fd(fd) })
}

fn start_time(proc: &OwnedFd) -> Result<u64> {
    let fd = proc_open(proc, "stat", libc::O_RDONLY | libc::O_NOFOLLOW)?;
    let mut text = String::new();
    File::from(fd).take(4096).read_to_string(&mut text)?;
    let fields = text.rsplit_once(") ").context("invalid process stat")?.1;
    fields
        .split_whitespace()
        .nth(19)
        .context("missing start time")?
        .parse()
        .context("invalid start time")
}

fn alive(pidfd: &OwnedFd) -> Result<()> {
    let mut p = libc::pollfd {
        fd: pidfd.as_raw_fd(),
        events: libc::POLLIN,
        revents: 0,
    };
    // SAFETY: p is a valid one-element poll buffer; timeout is nonblocking.
    let result = unsafe { libc::poll(&mut p, 1, 0) };
    ensure!(result == 0, "target process exited or pidfd check failed");
    Ok(())
}

fn metadata(fd: &OwnedFd) -> Result<std::fs::Metadata> {
    Ok(File::from(fd.try_clone()?).metadata()?)
}

fn fs_type(fd: &OwnedFd) -> Result<libc::c_long> {
    // SAFETY: statfs is an output-only POD buffer.
    let mut s: libc::statfs = unsafe { std::mem::zeroed() };
    ensure!(
        unsafe { libc::fstatfs(fd.as_raw_fd(), &mut s) } == 0,
        "fstatfs failed"
    );
    Ok(s.f_type)
}

fn mount_id(fd: &OwnedFd) -> Result<u64> {
    // SAFETY: statx is an output-only POD buffer; empty path addresses fd.
    let mut s: libc::statx = unsafe { std::mem::zeroed() };
    ensure!(
        unsafe {
            libc::statx(
                fd.as_raw_fd(),
                c"".as_ptr(),
                libc::AT_EMPTY_PATH,
                libc::STATX_MNT_ID,
                &mut s,
            )
        } == 0
            && s.stx_mask & libc::STATX_MNT_ID != 0,
        "statx mount ID unavailable"
    );
    Ok(s.stx_mnt_id)
}

#[repr(C)]
struct OpenHow {
    flags: u64,
    mode: u64,
    resolve: u64,
}

fn target(root: &OwnedFd) -> Result<OwnedFd> {
    let how = OpenHow {
        flags: (libc::O_PATH | libc::O_DIRECTORY | libc::O_CLOEXEC) as u64,
        mode: 0,
